<?php
namespace App\Livewire\Documents;
use App\Domain\Documents\Services\DuplicateCandidateService;use App\Domain\Documents\Services\RegisterDocument as RegisterAction;use App\Models\{District,DocumentCategory,DocumentType,Mouza,RevenueCircle,State,Village};use Illuminate\Validation\Rule;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')]
class RegisterDocument extends Component{public ?int $document_category_id=null,$document_type_id=null,$district_id=null,$revenue_circle_id=null,$mouza_id=null,$village_id=null,$record_year=null;public string $title='',$patta_no='',$dag_no='',$landholder_name='',$guardian_name='',$physical_file_reference='',$remarks='';public array $duplicates=[];public bool $duplicateAcknowledged=false;public function updatedDocumentCategoryId(){ $this->document_type_id=null; }public function checkDuplicates(DuplicateCandidateService $service):void{$this->validate($this->rules());$this->duplicates=$service->find($this->payload())->map->only(['ulid','reference_no','title','patta_no','dag_no','record_year'])->all();}public function register(RegisterAction $action,DuplicateCandidateService $dupes):void{$this->authorizePermission();$data=$this->validate($this->rules());$matches=$dupes->find($data);if($matches->isNotEmpty()&&!$this->duplicateAcknowledged){$this->duplicates=$matches->map->only(['ulid','reference_no','title','patta_no','dag_no','record_year'])->all();$this->addError('duplicateAcknowledged','Potential duplicate records exist. Review and acknowledge before registering.');return;}$state=State::where('code','AS')->firstOrFail();$data['state_id']=$state->id;$document=$action->execute($data,auth()->id());session()->flash('registered_reference',$document->reference_no);$this->redirectRoute('documents.show',$document,navigate:true);}private function authorizePermission():void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.register'),403);}private function payload():array{return ['document_category_id'=>$this->document_category_id,'document_type_id'=>$this->document_type_id,'district_id'=>$this->district_id,'revenue_circle_id'=>$this->revenue_circle_id,'mouza_id'=>$this->mouza_id,'village_id'=>$this->village_id,'title'=>$this->title,'patta_no'=>$this->patta_no?:null,'dag_no'=>$this->dag_no?:null,'landholder_name'=>$this->landholder_name?:null,'guardian_name'=>$this->guardian_name?:null,'record_year'=>$this->record_year,'physical_file_reference'=>$this->physical_file_reference?:null,'remarks'=>$this->remarks?:null];}private function rules():array{return ['document_category_id'=>['required',Rule::exists('document_categories','id')->where('is_active',true)],'document_type_id'=>['required',Rule::exists('document_types','id')->where('is_active',true)],'district_id'=>['required',Rule::exists('districts','id')->where('is_active',true)],'revenue_circle_id'=>['required',Rule::exists('revenue_circles','id')->where('is_active',true)],'mouza_id'=>['nullable','exists:mouzas,id'],'village_id'=>['nullable','exists:villages,id'],'title'=>['required','string','max:500'],'patta_no'=>['nullable','string','max:100'],'dag_no'=>['nullable','string','max:100'],'landholder_name'=>['nullable','string','max:500'],'guardian_name'=>['nullable','string','max:500'],'record_year'=>['nullable','integer','min:1700','max:'.now()->year],'physical_file_reference'=>['nullable','string','max:255'],'remarks'=>['nullable','string','max:5000']];}public function render(){return view('livewire.documents.register-document',['categories'=>DocumentCategory::where('is_active',true)->orderBy('sort_order')->get(),'types'=>DocumentType::where('is_active',true)->when($this->document_category_id,fn($q)=>$q->where('document_category_id',$this->document_category_id))->orderBy('sort_order')->get(),'districts'=>District::where('is_active',true)->orderBy('name_en')->get(),'circles'=>RevenueCircle::where('is_active',true)->when($this->district_id,fn($q)=>$q->where('district_id',$this->district_id))->orderBy('name_en')->get(),'mouzas'=>Mouza::where('is_active',true)->when($this->revenue_circle_id,fn($q)=>$q->where('revenue_circle_id',$this->revenue_circle_id))->orderBy('name_en')->get(),'villages'=>Village::where('is_active',true)->when($this->mouza_id,fn($q)=>$q->where('mouza_id',$this->mouza_id))->orderBy('name_en')->get()]);}}
